#include "benchmark.h"
#include <cuda.h>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>
namespace gcb {
#define CUCHK(c) do{CUresult r=(c);if(r!=CUDA_SUCCESS){const char*n="";const char*s="";cuGetErrorName(r,&n);cuGetErrorString(r,&s);throw std::runtime_error(std::string(#c)+" failed: "+n+" - "+s);}}while(0)
using Clock=std::chrono::steady_clock; constexpr int WARMUP=3;
double hostMs(Clock::time_point a,Clock::time_point b){return std::chrono::duration<double,std::milli>(b-a).count();}
double pct(std::vector<double>v,double p){if(v.empty())return 0;std::sort(v.begin(),v.end());return v[(size_t)std::ceil(p*(v.size()-1))];}
std::string ptx(){return GCB_KERNEL_PTX_PATH;}
struct Primary{CUdevice dev{};CUcontext ctx{};explicit Primary(CUdevice d):dev(d){CUCHK(cuDevicePrimaryCtxRetain(&ctx,d));CUCHK(cuCtxSetCurrent(ctx));}~Primary(){if(ctx){cuCtxSetCurrent(ctx);cuDevicePrimaryCtxRelease(dev);}}Primary(const Primary&)=delete;};
struct GC{CUgreenCtx green{};CUcontext ctx{};CUstream stream{};CUmodule mod{};CUfunction burn{},fma{},triad{};unsigned sms{};GC()=default;GC(const GC&)=delete;GC&operator=(const GC&)=delete;GC(GC&&x)noexcept:green(x.green),ctx(x.ctx),stream(x.stream),mod(x.mod),burn(x.burn),fma(x.fma),triad(x.triad),sms(x.sms){x.green=nullptr;x.ctx=nullptr;x.stream=nullptr;x.mod=nullptr;}~GC(){if(ctx)cuCtxSetCurrent(ctx);if(stream)cuStreamDestroy(stream);if(mod)cuModuleUnload(mod);if(green)cuGreenCtxDestroy(green);}};
void load(GC&g){CUCHK(cuCtxSetCurrent(g.ctx));auto p=ptx();CUCHK(cuModuleLoad(&g.mod,p.c_str()));CUCHK(cuModuleGetFunction(&g.burn,g.mod,"burn"));CUCHK(cuModuleGetFunction(&g.fma,g.mod,"fmaProbe"));CUCHK(cuModuleGetFunction(&g.triad,g.mod,"triad"));}
GC makeGC(const CUdevResource*r,unsigned n,CUdevice d){CUdevResourceDesc desc{};CUCHK(cuDevResourceGenerateDesc(&desc,const_cast<CUdevResource*>(r),n));GC g;CUCHK(cuGreenCtxCreate(&g.green,desc,d,CU_GREEN_CTX_DEFAULT_STREAM));CUCHK(cuCtxFromGreenCtx(&g.ctx,g.green));CUCHK(cuCtxSetCurrent(g.ctx));CUCHK(cuGreenCtxStreamCreate(&g.stream,g.green,CU_STREAM_NON_BLOCKING,0));CUdevResource actual{};CUCHK(cuGreenCtxGetDevResource(g.green,&actual,CU_DEV_RESOURCE_TYPE_SM));g.sms=actual.sm.smCount;load(g);return g;}
GC makeGC(const CUdevResource&r,CUdevice d){return makeGC(&r,1,d);}
std::vector<CUdevResource> split(CUdevice d,unsigned x,unsigned n){CUdevResource all{};CUCHK(cuDeviceGetDevResource(d,&all,CU_DEV_RESOURCE_TYPE_SM));if(!x||x>=n)throw std::runtime_error("invalid SM partition");CU_DEV_SM_RESOURCE_GROUP_PARAMS p[2]{};p[0].smCount=x;p[1].smCount=n-x;CUdevResource r[2]{};CUCHK(cuDevSmResourceSplit(r,2,&all,nullptr,0,p));return{r[0],r[1]};}
unsigned long long cycles(double t,CUdevice d){int khz=0;CUCHK(cuDeviceGetAttribute(&khz,CU_DEVICE_ATTRIBUTE_CLOCK_RATE,d));return(unsigned long long)(std::max(1.0,t)*khz*1000.0);}
void launch(CUfunction f,CUcontext c,CUstream s,CUdevice d,double t,int blocks,unsigned long long seed){CUCHK(cuCtxSetCurrent(c));auto cyc=cycles(t,d);void*a[]={&cyc,&seed};CUCHK(cuLaunchKernel(f,std::max(1,blocks),1,1,256,1,1,0,s,a,nullptr));}
CUevent event(CUcontext c){CUCHK(cuCtxSetCurrent(c));CUevent e{};CUCHK(cuEventCreate(&e,CU_EVENT_DEFAULT));return e;}
void record(CUcontext c,CUevent e,CUstream s){CUCHK(cuCtxSetCurrent(c));CUCHK(cuEventRecord(e,s));}
void wait(CUcontext c,CUevent e){CUCHK(cuCtxSetCurrent(c));CUCHK(cuEventSynchronize(e));}
double eventMs(CUcontext c,CUevent a,CUevent b){CUCHK(cuCtxSetCurrent(c));float x=0;CUCHK(cuEventElapsedTime(&x,a,b));return x;}
void destroyEvent(CUcontext c,CUevent e){if(e){cuCtxSetCurrent(c);cuEventDestroy(e);}}
void csvHeader(const std::string&p){std::ofstream f(p);if(!f)throw std::runtime_error("cannot open CSV");f<<"suite,mode,iterations,latency_p50_ms,latency_p95_ms,latency_p99_ms,kernel_gpu_time_ms,throughput_value,throughput_unit,background_time_ms,critical_sm_count,background_sm_count,critical_sm_ratio,background_sm_ratio\n";}
void emit(const Options&o,const std::string&suite,const std::string&mode,const std::vector<double>&v,double gpu,double bg,int cs,int bs,int total,const std::string&unit="kernels/s"){double p50=pct(v,.5),p95=pct(v,.95),p99=pct(v,.99);std::ofstream f(o.csv,std::ios::app);f<<suite<<','<<mode<<','<<v.size()<<','<<p50<<','<<p95<<','<<p99<<','<<gpu<<','<<(p50?1000/p50:0)<<','<<unit<<','<<bg<<',';if(cs<0)f<<"NA,NA,NA,NA\n";else f<<cs<<','<<bs<<','<<100.0*cs/total<<','<<100.0*bs/total<<'\n';std::cout<<suite<<'/'<<mode<<" P50="<<p50<<"ms P95="<<p95<<"ms P99="<<p99<<"ms\n";}
void measure(const Options&o,const std::string&suite,const std::string&mode,CUdevice d,CUcontext cc,CUstream cs,CUfunction cf,CUcontext bc,CUstream bs,CUfunction bf,int cb,int bb,int csm,int bsm,int total){auto a=event(cc),z=event(cc),be=event(bc);std::vector<double>v;double gpu=0,bg=0;int n=std::max(1,o.iterations);for(int i=-WARMUP;i<n;i++){auto bt=Clock::now();launch(bf,bc,bs,d,4,bb,i+1000);record(bc,be,bs);std::this_thread::sleep_for(std::chrono::milliseconds(1));auto st=Clock::now();record(cc,a,cs);launch(cf,cc,cs,d,.8,cb,i+2000);record(cc,z,cs);wait(cc,z);double h=hostMs(st,Clock::now());wait(bc,be);double b=hostMs(bt,Clock::now());if(i>=0){v.push_back(h);gpu+=eventMs(cc,a,z);bg+=b;}}destroyEvent(cc,a);destroyEvent(cc,z);destroyEvent(bc,be);emit(o,suite,mode,v,gpu/n,bg/n,csm,bsm,total);}
CUstream primaryStream(CUcontext c){CUCHK(cuCtxSetCurrent(c));CUstream s{};CUCHK(cuStreamCreate(&s,CU_STREAM_NON_BLOCKING));return s;}
CUfunction primaryBurn(CUcontext c,CUmodule&m){CUCHK(cuCtxSetCurrent(c));auto p=ptx();CUCHK(cuModuleLoad(&m,p.c_str()));CUfunction f{};CUCHK(cuModuleGetFunction(&f,m,"burn"));return f;}
void runPrimaryVsGreenContextComparison(const Options&o,CUdevice d,CUcontext p,unsigned n){CUmodule m{};auto f=primaryBurn(p,m);auto a=primaryStream(p),b=primaryStream(p);measure(o,"primary_vs_green_context_comparison","primary_two_streams",d,p,a,f,p,b,f,n*4,n*8,-1,-1,n);cuCtxSetCurrent(p);cuStreamDestroy(a);cuStreamDestroy(b);cuModuleUnload(m);auto r=split(d,n/2,n);GC c=makeGC(r[0],d),bg=makeGC(r[1],d);measure(o,"primary_vs_green_context_comparison","two_green_contexts",d,c.ctx,c.stream,c.burn,bg.ctx,bg.stream,bg.burn,c.sms*4,bg.sms*8,c.sms,bg.sms,n);}
void runSmPartitionSweep(const Options&o,CUdevice d,unsigned n,unsigned al){for(unsigned q=20;q<=80;q+=10){unsigned x=std::max(al,(unsigned)std::round(n*q/100.0/al)*al);if(x>=n)x=n-al;try{auto r=split(d,x,n);GC c=makeGC(r[0],d),b=makeGC(r[1],d);measure(o,"sm_partition_sweep",std::to_string(q)+"pct_critical",d,c.ctx,c.stream,c.burn,b.ctx,b.stream,b.burn,c.sms*4,b.sms*8,c.sms,b.sms,n);}catch(const std::exception&e){std::cerr<<"SKIP split "<<q<<"%: "<<e.what()<<'\n';}}}
void runMultiGreenContextConcurrency(const Options&o,CUdevice d,unsigned n,unsigned al){for(unsigned count:{2u,4u,8u}){unsigned groups=count,min=std::max(al,(n/count/al)*al);CUdevResource all{},parts[8]{};CUCHK(cuDeviceGetDevResource(d,&all,CU_DEV_RESOURCE_TYPE_SM));CUresult sr=cuDevSmResourceSplitByCount(parts,&groups,&all,nullptr,0,min);if(sr!=CUDA_SUCCESS||groups!=count){std::cerr<<"SKIP multi-context "<<count<<'\n';continue;}std::vector<GC>g;g.reserve(count);for(unsigned i=0;i<count;i++)g.push_back(makeGC(parts[i],d));std::vector<CUevent>done(count);for(unsigned i=1;i<count;i++){done[i]=event(g[i].ctx);}auto a=event(g[0].ctx),z=event(g[0].ctx);std::vector<double>v;double gpu=0,bg=0;for(int it=-WARMUP;it<std::max(1,o.iterations);it++){auto bt=Clock::now();for(unsigned i=1;i<count;i++){launch(g[i].burn,g[i].ctx,g[i].stream,d,8,g[i].sms*8,it*31+i);record(g[i].ctx,done[i],g[i].stream);}auto st=Clock::now();record(g[0].ctx,a,g[0].stream);launch(g[0].burn,g[0].ctx,g[0].stream,d,.8,g[0].sms*4,it+77);record(g[0].ctx,z,g[0].stream);wait(g[0].ctx,z);double h=hostMs(st,Clock::now());for(unsigned i=1;i<count;i++)wait(g[i].ctx,done[i]);double b=hostMs(bt,Clock::now());if(it>=0){v.push_back(h);gpu+=eventMs(g[0].ctx,a,z);bg+=b;}}for(unsigned i=1;i<count;i++)destroyEvent(g[i].ctx,done[i]);destroyEvent(g[0].ctx,a);destroyEvent(g[0].ctx,z);int back=0;for(unsigned i=1;i<count;i++)back+=g[i].sms;emit(o,"multi_green_context_concurrency",std::to_string(count)+"_green_contexts",v,gpu/v.size(),bg/v.size(),g[0].sms,back,n);}}
void runWorkqueueScopeComparison(const Options&o,CUdevice d,unsigned n){for(CUdevWorkqueueConfigScope scope:{CU_WORKQUEUE_SCOPE_DEVICE_CTX,CU_WORKQUEUE_SCOPE_GREEN_CTX_BALANCED}){auto r=split(d,n/2,n);CUdevResource wq{};CUCHK(cuDeviceGetDevResource(d,&wq,CU_DEV_RESOURCE_TYPE_WORKQUEUE_CONFIG));wq.wqConfig.sharingScope=scope;wq.wqConfig.wqConcurrencyLimit=std::max(1u,std::min(2u,wq.wqConfig.wqConcurrencyLimit));CUdevResource a[2]={r[0],wq},b[2]={r[1],wq};GC c=makeGC(a,2,d),bg=makeGC(b,2,d);measure(o,"workqueue_scope_comparison",scope==CU_WORKQUEUE_SCOPE_DEVICE_CTX?"device_ctx_scope":"green_ctx_balanced",d,c.ctx,c.stream,c.burn,bg.ctx,bg.stream,bg.burn,c.sms*4,bg.sms*4,c.sms,bg.sms,n);}}
void runComputeAndMemoryThroughput(const Options&o,CUcontext p){CUCHK(cuCtxSetCurrent(p));CUmodule m{};auto path=ptx();CUCHK(cuModuleLoad(&m,path.c_str()));CUfunction f{},t{};CUCHK(cuModuleGetFunction(&f,m,"fmaProbe"));CUCHK(cuModuleGetFunction(&t,m,"triad"));CUstream s{};CUCHK(cuStreamCreate(&s,CU_STREAM_NON_BLOCKING));const int n=1<<24,th=256,blocks=(n+th-1)/th,inner=8192;size_t bytes=(size_t)n*sizeof(float);CUdeviceptr a{},b{},c{},d{};CUCHK(cuMemAlloc(&a,bytes));CUCHK(cuMemAlloc(&b,bytes));CUCHK(cuMemAlloc(&c,bytes));CUCHK(cuMemAlloc(&d,bytes));CUCHK(cuMemsetD8(a,1,bytes));CUCHK(cuMemsetD8(b,2,bytes));CUevent e0{},e1{};CUCHK(cuEventCreate(&e0,CU_EVENT_DEFAULT));CUCHK(cuEventCreate(&e1,CU_EVENT_DEFAULT));int count=std::max(1,o.iterations);std::vector<double>fm,tm;for(int it=-WARMUP;it<count;it++){void*fa[]={&d,const_cast<int*>(&n),const_cast<int*>(&inner)};CUCHK(cuEventRecord(e0,s));CUCHK(cuLaunchKernel(f,blocks,1,1,th,1,1,0,s,fa,nullptr));CUCHK(cuEventRecord(e1,s));CUCHK(cuEventSynchronize(e1));float x=0;CUCHK(cuEventElapsedTime(&x,e0,e1));if(it>=0)fm.push_back(x);void*ta[]={&a,&b,&c,const_cast<int*>(&n)};CUCHK(cuEventRecord(e0,s));CUCHK(cuLaunchKernel(t,blocks,1,1,th,1,1,0,s,ta,nullptr));CUCHK(cuEventRecord(e1,s));CUCHK(cuEventSynchronize(e1));CUCHK(cuEventElapsedTime(&x,e0,e1));if(it>=0)tm.push_back(x);}double fms=pct(fm,.5),tms=pct(tm,.5),gf=(double)n*inner*2/(fms*1e6),gb=(double)n*12/(tms*1e6);std::ofstream out(o.csv,std::ios::app);out<<"compute_memory_throughput,fma_compute_probe,"<<count<<",NA,NA,NA,"<<fms<<','<<gf<<",GFLOP/s,NA,NA,NA,NA,NA\n";out<<"compute_memory_throughput,memory_triad_probe,"<<count<<",NA,NA,NA,"<<tms<<','<<gb<<",GB/s_nominal,NA,NA,NA,NA,NA\n";cuEventDestroy(e0);cuEventDestroy(e1);cuStreamDestroy(s);cuMemFree(a);cuMemFree(b);cuMemFree(c);cuMemFree(d);cuModuleUnload(m);}
void run(const Options&o){CUCHK(cuInit(0));int count=0;CUCHK(cuDeviceGetCount(&count));if(o.device<0||o.device>=count)throw std::runtime_error("invalid device ordinal");CUdevice d{};CUCHK(cuDeviceGet(&d,o.device));char name[256]{};CUCHK(cuDeviceGetName(name,256,d));Primary p(d);CUdevResource sm{};CUCHK(cuDeviceGetDevResource(d,&sm,CU_DEV_RESOURCE_TYPE_SM));unsigned n=sm.sm.smCount,al=std::max(1u,sm.sm.smCoscheduledAlignment);std::cout<<"GPU "<<name<<" | CUDA Driver API | SMs="<<n<<" alignment="<<al<<'\n';csvHeader(o.csv);if(o.suite==0||o.suite==1)runPrimaryVsGreenContextComparison(o,d,p.ctx,n);if(o.suite==0||o.suite==2)runSmPartitionSweep(o,d,n,al);if(o.suite==0||o.suite==3)runComputeAndMemoryThroughput(o,p.ctx);if(o.suite==0||o.suite==4)runMultiGreenContextConcurrency(o,d,n,al);if(o.suite==0||o.suite==5)runWorkqueueScopeComparison(o,d,n);}
}
int main(int argc,char**argv){try{gcb::Options o;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--device"&&i+1<argc)o.device=std::stoi(argv[++i]);else if(a=="--iterations"&&i+1<argc)o.iterations=std::max(1,std::stoi(argv[++i]));else if(a=="--suite"&&i+1<argc){std::string s=argv[++i];if(s=="all")o.suite=0;else if(s=="primary-vs-green")o.suite=1;else if(s=="sm-partition-sweep")o.suite=2;else if(s=="compute-memory-throughput")o.suite=3;else if(s=="multi-green-context")o.suite=4;else if(s=="workqueue-scope")o.suite=5;else throw std::runtime_error("unknown suite "+s);}else if(a=="--csv"&&i+1<argc)o.csv=argv[++i];else if(a=="--help"){std::cout<<"--suite all|primary-vs-green|sm-partition-sweep|compute-memory-throughput|multi-green-context|workqueue-scope --device N --iterations N --csv FILE\n";return 0;}else throw std::runtime_error("unknown argument "+a);}gcb::run(o);return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 1;}}
